g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "assumptions-table",
  "x": 64, "y": 180, "width": 1152, "height": 372,
  "strict_grid": true,
  "column_widths": [253, 611, 288],
  "row_heights": [44, 52, 52, 52, 52, 60, 60],
  "style": {
    "font_family": "Calibri",
    "font_size": 20,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 16, "right": 16, "top": 4, "bottom": 4},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Component", "bold": true, "align": "l"},
    {"text": "Model assumption", "bold": true, "align": "l"},
    {"text": "Basis / status", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"text": "Fund and calls", "bold": true, "color": "#003657"},
      {"text": "$20bn; $4bn at the start of Years 1–5"},
      {"text": "Question / model input", "color": "#5C6670"}
    ],
    [
      {"text": "Management fee", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "1.50% of commitments, paid in advance in Years 1–10", "fill": "#F1ECE2"},
      {"text": "Baseline fee, fixed model treatment", "color": "#5C6670", "fill": "#F1ECE2"}
    ],
    [
      {"text": "Asset growth", "bold": true, "color": "#003657"},
      {"text": "20% per year"},
      {"text": "Prescribed assumption", "color": "#5C6670"}
    ],
    [
      {"text": "Exits", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "20% at year-end in Years 5–9; full liquidation in Year 10", "fill": "#F1ECE2"},
      {"text": "Fixed model schedule", "color": "#5C6670", "fill": "#F1ECE2"}
    ],
    [
      {"text": "Distribution", "bold": true, "color": "#003657"},
      {"text": "Return contributed capital first; remaining profit split 80% LP / 20% GP"},
      {"text": "No-hurdle baseline", "color": "#5C6670"}
    ],
    [
      {"text": "Valuation", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "Model inception (t=0), 15% assumed discount rate, OPERF model share 3.75%", "fill": "#F1ECE2"},
      {"text": "Assumed rate, proportional model share", "color": "#5C6670", "fill": "#F1ECE2"}
    ]
  ]
}
